# Genius hero portrait matched to the user's reference look.
# SDXL 1.0 base (OpenRAIL++-M) + two IP-Adapter Plus SDXL adapters (Apache-2.0):
#   adapter 1 = the user's reference image (look, framing, light, materials)
#   adapter 2 = Kaggle portrait option 1 (the Genius identity: glasses, hair, brows)
import subprocess, time, base64, io
t0 = time.time()
subprocess.run("pip install -q -U diffusers transformers accelerate", shell=True, timeout=900)
import torch
from diffusers import StableDiffusionXLPipeline, AutoencoderKL
from transformers import CLIPVisionModelWithProjection
from PIL import Image, ImageDraw
def load(s): return Image.open(io.BytesIO(base64.b64decode(s))).convert("RGB")
STYLE, FACE = load(""), load("")
enc = CLIPVisionModelWithProjection.from_pretrained("h94/IP-Adapter", subfolder="models/image_encoder", torch_dtype=torch.float16)
vae = AutoencoderKL.from_pretrained("madebyollin/sdxl-vae-fp16-fix", torch_dtype=torch.float16)
pipe = StableDiffusionXLPipeline.from_pretrained("stabilityai/stable-diffusion-xl-base-1.0", vae=vae, image_encoder=enc,
       torch_dtype=torch.float16, variant="fp16", use_safetensors=True).to("cuda")
pipe.load_ip_adapter("h94/IP-Adapter", subfolder="sdxl_models",
       weight_name=["ip-adapter-plus_sdxl_vit-h.safetensors", "ip-adapter-plus-face_sdxl_vit-h.safetensors"])
CHAR = ("stylized 3D caricature of a nerdy Indian man behind a wooden table, centered, facing camera, oversized head, "
        "thin neck, big bulbous pink nose, huge round eyes, round thin black glasses, worried thick eyebrows, big ears, "
        "clean shaven, fuzzy black curly hair, white collared shirt, brown suspenders")
LOOK = ("photoreal miniature puppet photo, matte clay skin, real hair strands, real fabric texture, bright airy cafe, "
        "white tiled wall, wooden shelves, potted plants, dark green pendant lamps, soft daylight, 85mm f1.8, creamy bokeh")
NEG = ("beard, moustache, goatee, stubble, flannel, plaid, checkered shirt, text, logo, watermark, 2d, flat, drawing, "
       "dark room, deformed, extra fingers, multiple people, cropped head, lowres, ugly")
tiles = []
for sty, face in [(0.6, 0.35), (0.6, 0.55), (0.8, 0.35), (0.8, 0.55)]:
    pipe.set_ip_adapter_scale([sty, face])
    for seed in [21, 22]:
        img = pipe(prompt=CHAR, prompt_2=LOOK, negative_prompt=NEG, ip_adapter_image=[STYLE, FACE],
                   width=768, height=1344, num_inference_steps=40, guidance_scale=6.0,
                   generator=torch.Generator("cuda").manual_seed(seed)).images[0]
        img.save(f"/kaggle/working/genius_sty{int(sty*100)}_face{int(face*100)}_seed{seed}.png")
        tiles.append((f"look {sty} / face {face} / seed {seed}", img))
        print(len(tiles), f"{time.time()-t0:.0f}s", flush=True)
tw, th = 384, 672
sheet = Image.new("RGB", (tw * 4, (th + 30) * 2), "white"); d = ImageDraw.Draw(sheet)
for i, (lab, img) in enumerate(tiles):
    x, y = (i % 4) * tw, (i // 4) * (th + 30)
    d.text((x + 6, y + 8), f"option {i+1}: {lab}", fill="black")
    sheet.paste(img.resize((tw, th)), (x, y + 30))
sheet.save("/kaggle/working/genius_exact.jpg", quality=92)
print(f"TOTAL {time.time()-t0:.0f}s")
